// Moore state machine: one input, one output, explicit next state.
module TopModule(
    input  in,
    input  [1:0] state,
    output [1:0] next_state,
    output reg out
);
    reg [1:0] ns;
    always @(*) begin
        case (state)
            2'b00: begin ns = 2'b00; out = 1'b0; end
            2'b01: begin ns = 2'b01; out = 1'b0; end
            2'b10: begin ns = 2'b11; out = 1'b0; end
            2'b11: begin ns = 2'b00; out = 1'b1; end
        endcase
    end
    always @(posedge in) begin
        case (state)
            2'b00: next_state = (in) ? 2'b01 : 2'b00;
            2'b01: next_state = (in) ? 2'b10 : 2'b01;
            2'b10: next_state = (in) ? 2'b11 : 2'b00;
            2'b11: next_state = (in) ? 2'b01 : 2'b00;
        endcase
    end
endmodule

