module TopModule (
  input  in,
  input  [1:0] state,
  output [1:0] next_state,
  output reg out
);
  reg [1:0] ns_table [0:3][0:1];
  always @* begin
    ns_table[0][0] = 2'b00; ns_table[0][1] = 2'b01;
    ns_table[1][0] = 2'b10; ns_table[1][1] = 2'b01;
    ns_table[2][0] = 2'b00; ns_table[2][1] = 2'b11;
    ns_table[3][0] = 2'b10; ns_table[3][1] = 2'b01;
    next_state = ns_table[state][in];
    out = (next_state == 2'b10) ? 1'b1 : 1'b0;
  end
endmodule

